package dz.local.mealguard;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.time.*;import java.util.*;
public class ReplacementTest {
 JSONObject cfg;JSONArray depots;Engine.Meal target;JSONObject old;Fake api;EngineTest.Memory journal;
 class Fake implements Replacement.Gateway {
  JSONArray rows=new JSONArray();int cancels=0,writes=0,reads=0,depotReads=0;boolean keepOld=false,cancelTimeout=false,bookTimeout=false,bookRefused=false,failAfterCancel=false,failFinal=false;long cancelledId;int removeTargetAt=-1,failReadAt=-1;Runnable beforeCancel;
  public JSONArray depots()throws Exception{depotReads++;if(depotReads==removeTargetAt)depots.getJSONObject(1).put("lunch",false);return new JSONArray(depots.toString());}
  public JSONArray reservations()throws Exception{reads++;if(reads==failReadAt||failAfterCancel&&cancels>0&&writes==0||failFinal&&writes>0&&reads>=5)throw new Exception("offline");return new JSONArray(rows.toString());}
  public void cancel(long id)throws Exception{cancels++;cancelledId=id;if(beforeCancel!=null)beforeCancel.run();if(!keepOld){JSONArray next=new JSONArray();for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getLong("id")!=id)next.put(rows.getJSONObject(i));rows=next;}if(cancelTimeout)throw new Exception("lost DELETE response");}
  public void reserve(Engine.Meal m)throws Exception{writes++;if(!bookRefused)rows.put(new JSONObject().put("id",500).put("date_reserve",m.day.toString()).put("mealtype_fr",EngineTest.FR[m.type]).put("depot_fr",Engine.name(m.depot)));if(bookTimeout)throw new Exception("lost POST response");}
 }
 @Before public void setup()throws Exception{cfg=new JSONObject().put("breakfast_id",10).put("lunch_id",20).put("dinner_id",10);depots=new JSONArray().put(new JSONObject().put("id",10).put("nameFR","Dorm").put("breakfast",true).put("lunch",true).put("dinner",true)).put(new JSONObject().put("id",20).put("nameFR","Main").put("breakfast",false).put("lunch",true).put("dinner",false));target=Engine.plan(cfg,depots,new JSONArray(),Engine.today()).get(1);old=new JSONObject().put("id",77).put("date_reserve",target.day.toString()).put("mealtype_fr","lunch").put("depot_fr","Dorm");api=new Fake();api.rows.put(old);journal=new EngineTest.Memory();}
 List<Replacement.Conflict> approved()throws Exception{return Replacement.inspect(cfg,depots,api.rows,Engine.today()).conflicts;}
 String run(List<Replacement.Conflict> approved)throws Exception{return Replacement.apply(api,journal,cfg,approved,()->false);}
 @Test public void previewIsReadOnlyAndShowsOldAndNew()throws Exception{Replacement.Review r=Replacement.inspect(cfg,depots,api.rows,Engine.today());assertEquals(9,r.plan.size());assertEquals(1,r.conflicts.size());assertTrue(Replacement.describe(r.conflicts).contains("Dorm"));assertTrue(Replacement.describe(r.conflicts).contains("Main"));assertTrue(Replacement.describe(r.conflicts).contains("77"));assertEquals(0,api.cancels);assertEquals(0,api.writes);}
 @Test public void explicitReplacementCancelsOnlyApprovedIdAndCreatesOneMeal()throws Exception{assertTrue(run(approved()).contains("1"));assertEquals(1,api.cancels);assertEquals(77,api.cancelledId);assertEquals(1,api.writes);assertEquals(500,Engine.matching(api.rows,target));assertEquals(0,journal.j.length());}
 @Test public void noApprovalNoWrite()throws Exception{assertThrows(Engine.Problem.class,()->run(Collections.emptyList()));assertEquals(0,api.cancels);assertEquals(0,api.writes);}
 @Test public void alreadyMatchingReservationNotCancelled()throws Exception{old.put("depot_fr","Main");assertTrue(approved().isEmpty());assertThrows(Engine.Problem.class,()->run(approved()));assertEquals(0,api.cancels);}
 @Test public void staleReservationIdRequiresNewApproval()throws Exception{List<Replacement.Conflict> a=approved();old.put("id",78);assertThrows(Engine.Problem.class,()->run(a));assertEquals(0,api.cancels);}
 @Test public void changedSourceNameRequiresNewApproval()throws Exception{List<Replacement.Conflict> a=approved();old.put("depot_fr","Other");assertThrows(Engine.Problem.class,()->run(a));assertEquals(0,api.cancels);}
 @Test public void changedTargetRequiresNewApproval()throws Exception{List<Replacement.Conflict> a=approved();cfg.put("lunch_id",10);assertThrows(Engine.Problem.class,()->run(a));assertEquals(0,api.cancels);}
 @Test public void newUnapprovedConflictPreventsAllCancellations()throws Exception{List<Replacement.Conflict> a=approved();api.rows.put(new JSONObject(old.toString()).put("id",88).put("date_reserve",target.day.plusDays(1).toString()));assertThrows(Engine.Problem.class,()->run(a));assertEquals(0,api.cancels);}
 @Test public void duplicateSlotCannotBeReplaced()throws Exception{api.rows.put(new JSONObject(old.toString()).put("id",88));assertThrows(Engine.Problem.class,()->approved());assertEquals(0,api.cancels);}
 @Test public void missingIdCannotBeReplaced()throws Exception{old.put("id",0);assertThrows(Engine.Problem.class,()->approved());}
 @Test public void missingSourceNameCannotBeReplaced()throws Exception{old.remove("depot_fr");assertThrows(Engine.Problem.class,()->approved());}
 @Test public void unknownStatusCannotBeReplaced()throws Exception{old.put("status","used");assertThrows(Engine.Problem.class,()->approved());}
 @Test public void missingTargetOfferingPreventsCancellation()throws Exception{List<Replacement.Conflict> a=approved();depots.getJSONObject(1).put("lunch",false);assertThrows(Engine.Problem.class,()->run(a));assertEquals(0,api.cancels);}
 @Test public void disappearingOfferingBeforeDeletePreventsCancellation()throws Exception{List<Replacement.Conflict> a=approved();api.removeTargetAt=2;assertThrows(Engine.Problem.class,()->run(a));assertEquals(0,api.cancels);}
 @Test public void uncertainDeleteNeverCreatesOrReplays()throws Exception{List<Replacement.Conflict> a=approved();api.keepOld=true;api.cancelTimeout=true;assertThrows(Engine.Problem.class,()->run(a));assertEquals(1,api.cancels);assertEquals(0,api.writes);assertTrue(journal.j.has(target.key()));assertThrows(Engine.Problem.class,()->run(a));assertEquals(1,api.cancels);}
 @Test public void successResponseButOldStillVisibleDoesNotCreate()throws Exception{api.keepOld=true;assertThrows(Engine.Problem.class,()->run(approved()));assertEquals(0,api.writes);assertEquals("replacement_cancel_pending",journal.j.getJSONObject(target.key()).getString("state"));}
 @Test public void lostDeleteResponseReconciledByHistory()throws Exception{api.cancelTimeout=true;run(approved());assertEquals(1,api.cancels);assertEquals(1,api.writes);assertEquals(0,journal.j.length());}
 @Test public void historyFailureAfterDeleteLeavesLockAndDoesNotCreate()throws Exception{api.failAfterCancel=true;assertThrows(Engine.Problem.class,()->run(approved()));assertEquals(1,api.cancels);assertEquals(0,api.writes);assertTrue(journal.j.has(target.key()));}
 @Test public void lostReserveResponseReconciledWithoutReplay()throws Exception{api.bookTimeout=true;run(approved());assertEquals(1,api.writes);assertEquals(0,journal.j.length());}
 @Test public void failedReserveWarnsThatOldWasCancelledAndLocksOnlyItsOwnMeal()throws Exception{api.bookRefused=true;List<Replacement.Conflict> a=approved();Engine.Problem e=assertThrows(Engine.Problem.class,()->run(a));assertTrue(e.getMessage().contains("أُلغي الحجز القديم"));assertTrue(e.getMessage().contains("دون حجز"));assertEquals("replacement_create_pending",journal.j.getJSONObject(target.key()).getString("state"));api.bookRefused=false;assertThrows(Engine.Problem.class,()->Engine.apply(api,journal,Engine.plan(cfg,depots,api.rows,Engine.today()),()->false));assertEquals(9,api.writes);assertEquals(1,api.cancels);assertTrue(journal.j.has(target.key()));}
 @Test public void journalFailurePreventsDelete()throws Exception{Engine.Journal broken=new Engine.Journal(){public JSONObject load(){return new JSONObject();}public void save(JSONObject value)throws Exception{throw new Exception("disk full");}};assertThrows(Exception.class,()->Replacement.apply(api,broken,cfg,approved(),()->false));assertEquals(0,api.cancels);}
 @Test public void priorBookingLockPreventsDelete()throws Exception{journal.j.put(target.key(),new JSONObject().put("state","pending"));assertThrows(Engine.Problem.class,()->run(approved()));assertEquals(0,api.cancels);}
 @Test public void stoppedBeforeCancellationDoesNotWrite()throws Exception{assertThrows(Engine.Problem.class,()->Replacement.apply(api,journal,cfg,approved(),()->true));assertEquals(0,api.cancels);assertEquals(0,api.writes);}
 @Test public void stopAfterDeletePreservesCreateLock()throws Exception{assertThrows(Engine.Problem.class,()->Replacement.apply(api,journal,cfg,approved(),()->api.cancels>0));assertEquals(1,api.cancels);assertEquals(0,api.writes);assertEquals("replacement_create_pending",journal.j.getJSONObject(target.key()).getString("state"));}
 @Test public void newTargetBookingByOfficialAppAfterDeleteAvoidsPost()throws Exception{api.beforeCancel=()->{try{api.rows.put(new JSONObject().put("id",501).put("date_reserve",target.day.toString()).put("mealtype_fr","lunch").put("depot_fr","Main"));}catch(Exception e){throw new AssertionError(e);}};run(approved());assertEquals(0,api.writes);assertEquals(0,journal.j.length());}
 @Test public void finalReadFailureNeverClaimsSuccess()throws Exception{api.failFinal=true;assertThrows(Exception.class,()->run(approved()));assertEquals(1,api.cancels);assertEquals(1,api.writes);}
 @Test public void historyFailureBeforeDeletionDoesNotWrite()throws Exception{List<Replacement.Conflict> a=approved();api.failReadAt=2;assertThrows(Exception.class,()->run(a));assertEquals(0,api.cancels);}
}
